              layoutId={`billing-toggle-${id}`}
              className={cn("absolute inset-0 rounded-md", inverse ? "bg-white" : "bg-zinc-950")}
              transition={{ type: "spring", stiffness: 430, damping: 34 }}
            />
          )}
          <span className="relative z-10">{value}</span>
        </button>
      ))}
    </div>
  );
}

